create or replace function public.review_group_join_request(p_request_id uuid,p_approve boolean) returns jsonb language plpgsql security definer set search_path = '' as $$ declare v_req public.group_join_requests%rowtype; v_count integer; v_activated timestamptz; begin if auth.uid() is null then raise exception 'Sign in is required'; end if; select * into v_req from public.group_join_requests where id=p_request_id and status='pending' for update; if not found then raise exception 'Join request not found or already handled'; end if; if not exists(select 1 from public.group_members gm where gm.group_id=v_req.group_id and gm.user_id=auth.uid() and gm.role in ('creator','admin')) then raise exception 'Only group admins can review join requests'; end if; if not p_approve then update public.group_join_requests set status='declined',responded_at=now(),responded_by=auth.uid() where id=p_request_id; return jsonb_build_object('status','declined'); end if; insert into public.group_members(group_id,user_id,role) values(v_req.group_id,v_req.user_id,'member') on conflict(group_id,user_id) do nothing; update public.group_join_requests set status='approved',responded_at=now(),responded_by=auth.uid() where id=p_request_id; select count(*)::integer into v_count from public.group_members where group_id=v_req.group_id; if v_count>=3 then update public.chat_groups set activated_at=coalesce(activated_at,now()) where id=v_req.group_id returning activated_at into v_activated; end if; return jsonb_build_object('status','approved','member_count',v_count,'activated_at',v_activated); end; $$; grant execute on function public.review_group_join_request(uuid,boolean) to authenticated;
